const state={bootstrap:null,topics:[],sources:[],evidence:[],claims:[],judgments:[],route:'dashboard',dashboard:null,window:localStorage.getItem('wi-window')||'24h',offset:0,limit:20,topicFilter:'',since:'',until:'',query:'',timeline:'event',materialFilter:'',verificationFilter:'',judgmentStatus:'',judgmentType:'',judgmentTopic:'',reviewDue:false,mapCountry:'',selectedEvent:null};
const $=s=>document.querySelector(s);
let generation=0,toastTimer,dialogContext=null,mapCache=null;
const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${({dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><path d="M14 15h7m-7 5h7"/>',topics:'<path d="M3 6h7l2 3h9v11H3z"/><path d="M3 6V4h8l2 2h8v3"/>',evidence:'<path d="M5 3h10l4 4v14H5z"/><path d="M14 3v5h5M8 12h8M8 16h8"/>',judgments:'<path d="M5 4h14v17H5zM9 2v4m6-4v4M8 11l2 2 5-5M8 17h8"/>',map:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18M5 6h14M5 18h14"/>',sources:'<circle cx="6" cy="5" r="2"/><circle cx="18" cy="12" r="2"/><circle cx="6" cy="19" r="2"/><path d="M8 5h4v7h4M8 19h4v-7"/>',settings:'<path d="M5 5h14M5 12h14M5 19h14"/><circle cx="9" cy="5" r="2"/><circle cx="15" cy="12" r="2"/><circle cx="9" cy="19" r="2"/>'})[name]||''}</svg>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4800);}
function nav(name,text){return `<a class="nav-link ${state.route.split('/')[0]===name?'active':''}" href="#/${name}">${icon(name)}<span>${text}</span></a>`;}
function shell(){
 $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><a class="brand" href="#/dashboard"><span class="brand-mark">W</span><div><div class="brand-name">World Insight</div><div class="brand-sub">国际局势研究看板</div></div></a><div class="nav-label">研究工作台</div><nav aria-label="主导航">${nav('dashboard','变化简报')}${nav('topics','议题档案')}${nav('evidence','证据资料库')}${nav('judgments','我的判断')}${nav('map','地图与国家')}</nav><div class="nav-label" style="margin-top:30px">运行与管理</div><nav aria-label="设置">${nav('sources','来源管理')}${nav('settings','本地运行')}</nav><div class="sidebar-bottom"><strong><i class="dot"></i>私有 · 本地研究</strong>保留依据，允许未知<br>AI 与付费能力默认关闭</div></aside><div class="main-wrap"><header class="topbar"><div class="breadcrumb">工作空间<span>/ ${esc(({dashboard:'变化简报',topics:'议题档案',evidence:'证据资料库',judgments:'我的判断',map:'地图与国家',sources:'来源管理',settings:'本地运行'})[state.route.split('/')[0]]||'研究记录')}</span></div><div class="top-status"><span><i class="dot"></i>本地资料库已连接</span><span class="date">${esc(new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'short'}))}</span></div></header><main id="main" class="content" tabindex="-1"><div class="loading">正在读取研究记录</div></main></div></div>`;
}
const action=(name,text,extra='',classes='')=>`<button type="button" data-action="${name}" ${extra} class="${classes}">${esc(text)}</button>`;
const create=(kind,text,topicId='',classes='small')=>action('create',text,`data-kind="${kind}" data-topic="${esc(topicId)}"`,classes);
const edit=(kind,record,text='编辑')=>record.deleted?'<a class="button small" href="#/settings">前往回收站恢复</a>':action('edit',text,`data-kind="${kind}" data-id="${esc(record.id)}"`,'small')+deleteButton(kind,record);
const history=(kind,record)=>action('history',`版本 ${record.version}`,`data-kind="${kind}" data-id="${esc(record.id)}"`,'small ghost');
const empty=(title,text,button='')=>`<div class="empty"><h3>${esc(title)}</h3><p>${esc(text)}</p>${button?`<div class="actions">${button}</div>`:''}</div>`;
const head=(eyebrow,title,subtitle,buttons='')=>`<div class="page-heading"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p class="subtitle">${esc(subtitle)}</p></div><div class="actions">${buttons}</div></div>`;
const panel=(title,content,buttons='',number='',id='')=>`<section class="panel" ${id?`id="${id}"`:''}><div class="panel-head"><h2>${number?`<span class="section-number">${number}</span>`:''}${esc(title)}</h2><div class="actions">${buttons}</div></div>${content}</section>`;
const kv=rows=>`<dl class="kv">${rows.map(([key,value])=>`<dt>${esc(key)}</dt><dd>${value}</dd>`).join('')}</dl>`;
const textKv=rows=>kv(rows.map(([key,value])=>[key,esc(value??'未知')]));
const link=(url,text='查看原文')=>safeURL(url)?`<a href="${esc(safeURL(url))}" target="_blank" rel="noopener noreferrer">${esc(text)} ↗</a>`:'<span class="muted">原链接未登记</span>';
const topicName=id=>state.topics.find(x=>x.id===id)?.question||'未关联议题';
function cite(ids=[]){return `<div class="citations">${ids.map(id=>{const eid=String(id).split('@')[0];const e=state.evidence.find(x=>x.id===eid);return `<a class="citation" href="#/evidence/${encodeURIComponent(eid)}?version=${encodeURIComponent(String(id).split('@')[1]||'')}">${esc(e&&String(e.version)===String(id).split('@')[1]?e.title:'历史材料')} · v${esc(String(id).split('@')[1]||'?')}</a>`;}).join('')}</div>`;}
function assumptionNotice(record){if(record.evidence_support==='assumption_only'||!(record.evidence_version_ids||[]).length)return '<div class="notice">假设型暂定判断／缺乏证据支持。用户已审阅不表示已证明属实。</div>';return record.missing_evidence?`<div class="notice">仍缺少证据：${esc(record.missing_evidence)}。已登记引用仍需核查。</div>`:'';}
async function context(){const [topics,sources,evidence,claims,judgments]=await Promise.all(['/topics','/sources','/evidence','/claims','/judgments'].map(path=>api(path+'?limit=200').catch(error=>{if(path==='/sources')return {items:[],error:error.message};throw error;})));Object.assign(state,{topics:items(topics),sources:items(sources),evidence:items(evidence),claims:items(claims),judgments:items(judgments)});}
async function route(){const my=++generation;state.route=decodeURIComponent(location.hash.replace(/^#\/?/,'').split('?')[0]||'dashboard');shell();try{if(!state.bootstrap)state.bootstrap=await api('/bootstrap');await context();let html;const [name,id]=state.route.split('/');if(name==='dashboard')html=await dashboard();else if(name==='topics')html=id?await topicDetail(id):topicsPage();else if(name==='evidence')html=id?await evidenceDetail(id):await evidencePage();else if(name==='judgments')html=await judgmentsPage();else if(name==='sources')html=await sourcesPage();else if(name==='map')html=await mapPage();else if(name==='settings')html=await settingsPage();else html=empty('页面不存在','请通过左侧导航返回研究工作台。');if(my!==generation)return;$('#main').innerHTML=html;if(name==='map'||name==='topics'&&id)renderMaps();}catch(error){if(my!==generation)return;$('#main').innerHTML=`${head('LOCAL WORKSPACE','暂时无法读取资料库','已有记录仍保存在本地数据目录。')}<div class="notice danger">${esc(error.message)}</div>${action('reload','重试连接','','primary')}<p class="small-text muted" style="margin-top:15px">请确认启动入口仍在运行。第三方来源离线不会影响本地人工研究。</p>`;}}
function coverageNotice(coverage){const status=coverage?.coverage_status||coverage?.status||'not_configured';const message=coverage?.explanation||({unavailable:'启用的来源检查失败，无法判断是否有新变化。',partial:'部分来源尚未检查成功；当前资料只代表已完成的覆盖范围。',not_configured:'自动来源尚未配置。可先人工登记材料，核心研究功能正常可用。',complete:'已配置来源的本轮检查已完成；不代表对全球事件的完整覆盖。'})[status]||'来源覆盖情况未知。';return `<div class="notice ${status==='complete'?'info':''}"><strong>${esc(label(status))}</strong> · ${esc(message)} <a href="#/sources">查看逐源状态 →</a></div>`;}
async function dashboard(){
 const query=new URLSearchParams({window:state.window,offset:String(state.offset),limit:String(state.limit)});if(state.topicFilter)query.set('topic_id',state.topicFilter);if(state.since)query.set('since',state.since);if(state.until)query.set('until',state.until);
 const d=await api('/dashboard?'+query);state.dashboard=d;const changes=items(d.changes||d);const topics=(items(d.topics).length?items(d.topics):state.topics).filter(x=>x.followed!==false&&x.status==='active');const notificationPage=await api('/notifications?status=unread&limit=20&offset='+(state.notificationOffset||0));const notifications=items(notificationPage);const due=items(d.review_due);const needs=due.filter(x=>x.status==='needs_review');
 const windows=[['unread','自上次阅读'],['24h','24 小时'],['7d','7 天'],['custom','自定义']];
 const onboarding=!state.topics.length?`<div class="onboarding" style="margin-bottom:24px"><div class="eyebrow">开始你的第一项研究</div><h2>让每一次判断，都有可以回看的依据</h2><p style="margin-top:8px">从一个具体问题开始。没有任何模型或收费密钥，也能完成资料整理、判断与复盘。</p><div class="steps"><div class="step"><b>01</b> 建立议题<span>明确问题和研究范围</span></div><div class="step"><b>02</b> 登记材料<span>保留原文与材料版本</span></div><div class="step"><b>03</b> 形成判断<span>列出证据、假设和反证</span></div><div class="step"><b>04</b> 跟踪复盘<span>记录何时、为何改变看法</span></div></div><div class="actions" style="margin-top:20px">${create('topics','＋ 创建首个议题','','primary')}</div></div>`:'';
 return head('DAILY RESEARCH BRIEF','今天，哪些变化值得重新关注？','从发现时间观察新增，从原始材料理解变化。简报由规则与研究记录生成。',`${action('reload','刷新本地记录')}${create('topics','＋ 新建议题','','primary')}`)+onboarding+`<div class="stats"><div class="stat"><div class="stat-label">关注中的议题</div><div class="stat-value">${topics.length}</div><div class="stat-foot">${state.topics.filter(x=>x.status==='paused').length} 个已暂停</div></div><div class="stat"><div class="stat-label">所选窗口的变化</div><div class="stat-value">${esc(d.total??changes.length)}</div><div class="stat-foot">按发现时间统计</div></div><div class="stat"><div class="stat-label">需要重新审阅</div><div class="stat-value">${needs.length}</div><div class="stat-foot">已登记依赖受到更正影响</div></div><div class="stat"><div class="stat-label">到期复查</div><div class="stat-value">${due.length}</div><div class="stat-foot">标记已读不会完成复查</div></div></div>`+coverageNotice(d.coverage)+`<div class="toolbar"><div class="segmented">${windows.map(([v,t])=>action('window',t,`data-value="${v}"`,state.window===v?'selected':'')).join('')}</div><select aria-label="筛选关注议题" data-filter="dashboard-topic"><option value="">全部关注议题</option>${state.topics.map(t=>`<option value="${esc(t.id)}" ${state.topicFilter===t.id?'selected':''}>${esc(t.question)}</option>`).join('')}</select></div>${state.window==='custom'?`<div class="toolbar"><label>开始 <input type="datetime-local" data-filter="since" value="${esc(state.since)}"></label><label>结束 <input type="datetime-local" data-filter="until" value="${esc(state.until)}"></label>${action('apply-window','应用时间范围')}</div>`:''}<div class="grid-main"><div>${panel('变化记录',changes.length?changes.map(changeCard).join('')+pagination(d):empty(d.summary||'所选范围未发现新增记录','请结合来源覆盖与检查时间判断；当前范围内没有记录不等于现实没有事件。'),action('mark-read','将本页已展示变化标为已读',changes.length?'':'disabled','small'))}<p class="muted small-text">优先展示证据更正与到期复查，其次为关注规则。新闻数量不单独构成风险升级。快照：${esc(date(d.snapshot_at))}</p>${panel('关注议题',`<div class="panel-body grid-2">${topics.length?topics.map(topicCard).join(''):empty('还没有关注议题','新建议题或在已有议题中开启关注。')}</div>`)}</div><aside>${panel('研究待办',needs.length||due.length?[...new Map([...needs,...due].map(x=>[x.id,x])).values()].map(j=>`<div class="record"><div class="badges">${badge(j.status)}${j.review_date?`<span class="small-text muted">复查 ${esc(j.review_date)}</span>`:''}</div><p style="margin-top:8px"><a href="#/topics/${esc(j.topic_id)}">${esc(j.conclusion||j.title||'待复查判断')}</a></p><div class="actions">${edit(reviewTarget(j).collection,j,reviewTarget(j).label)}${reviewTarget(j).canReview?action('review','记录复盘',`data-id="${esc(j.id)}"`,'small ghost'):''}</div></div>`).join(''):empty('暂无待办','待核查、到期复查与待重审会在这里保留。'))}${panel('站内提醒',`<div class="panel-body small-text">共 ${notificationPage.total} 条未读提醒</div>`+(notifications.map(n=>`<div class="record"><p class="small-text">${esc(n.reason||n.title||'研究记录需要关注')}</p><div class="record-actions">${n.topic_id?`<a href="#/topics/${esc(n.topic_id)}">打开议题</a>`:''}${action('notification-read','标记提醒已读',`data-id="${esc(n.id)}"`,'small ghost')}</div></div>`).join('')||empty('暂无未读提醒','站内提醒与研究待办分别管理。'))+pagination({...notificationPage,limit:20},state.notificationOffset||0,'notification-page'))}${panel('研究原则',`<div class="panel-body small-text muted"><p>说法不等于已落实的事实。</p><p>多个转载不等于多方独立证实。</p><p>未知值保留未知，事件发生时间与采集时间分别记录。</p><p>“已审阅”表示用户完成审阅。</p></div>`)}</aside></div>`;
}
function changeCard(c){
 const domain=String(c.type||'').split('.')[0];
 const href=domain==='evidence'?`#/evidence/${encodeURIComponent(c.aggregate_id)}`:domain==='source'?'#/sources':c.topic_id?`#/topics/${encodeURIComponent(c.topic_id)}`:'';
 const title=c.detail||c.title||c.reason||'研究记录变化';
 const historyKind=({event:'events',claim:'claims',judgment:'judgments'})[domain];
 return `<article class="record change-item"><i class="change-dot ${c.needs_review||c.type?.includes('correct')?'warning':''}"></i><div><div class="change-type">${esc(c.title||label(c.type))}${c.needs_review?' · 待重审':''}</div><div class="record-title">${href?`<a href="${esc(href)}">${esc(title)}</a>`:esc(title)}</div><div class="record-meta"><span>${esc(topicName(c.topic_id))}</span><span>事件发生：${esc(date(c.occurred_at,c.time_precision))}</span>${c.unverified?badge('unverified'):c.status?badge(c.status):''}</div>${c.evidence_support==='assumption_only'||c.missing_evidence?assumptionNotice(c):''}${cite(c.evidence_version_ids)}${historyKind?`<div class="record-actions">${action('history','查看原记录与版本',`data-kind="${historyKind}" data-id="${esc(c.aggregate_id)}"`,'small ghost')}</div>`:''}</div><div class="change-time">发现 ${esc(date(c.discovered_at||c.created_at))}</div></article>`;
}
function pagination(d,offset=state.offset,actionName='page'){const pageSize=d.limit||state.limit;return `<div class="pagination"><span>第 ${Math.floor(offset/pageSize)+1} 页 · 共 ${esc(d.total??0)} 条</span><div class="actions">${action(actionName,'上一页',`data-offset="${Math.max(0,offset-pageSize)}" ${offset?'':'disabled'}`,'small')}${action(actionName,'下一页',`data-offset="${offset+pageSize}" ${offset+pageSize<(d.total||0)?'':'disabled'}`,'small')}</div></div>`;}
function topicCard(t){const current=state.judgments.filter(j=>j.topic_id===t.id&&j.status!=='withdrawn').sort((a,b)=>String(b.updated_at).localeCompare(String(a.updated_at)))[0];return `<article class="topic-card"><div class="badges">${badge(t.status)}${t.followed?'<span class="small-text muted">已关注</span>':''}</div><h3 class="question"><a href="#/topics/${esc(t.id)}">${esc(t.question)}</a></h3><div class="small-text muted">${esc((t.regions||[]).join(' · ')||'地区范围尚未填写')}</div>${current?`<div class="small-text"><span class="muted">当前判断</span><p>${esc(current.conclusion)}</p>${current.status==='needs_review'?badge('needs_review'):''}${current.missing_evidence||!current.evidence_version_ids?.length?badge('unknown','缺乏证据支持'):''}</div>`:'<div class="small-text muted">尚未形成判断</div>'}<div class="topic-footer"><span>更新 ${esc(date(t.updated_at))}</span><a href="#/topics/${esc(t.id)}">打开档案 →</a></div></article>`;}
function topicsPage(){const filtered=state.topics.filter(t=>!state.query||JSON.stringify(t).toLowerCase().includes(state.query.toLowerCase()));return head('RESEARCH TOPICS','议题档案','用一个持续研究的问题组织材料、事件与判断。暂停与归档保留全部历史。',create('topics','＋ 新建议题','','primary'))+`<div class="toolbar"><span class="small-text muted">${state.topics.length} 个议题 · ${state.topics.filter(t=>t.status==='active').length} 个进行中</span><input type="search" aria-label="搜索议题" data-filter="search" value="${esc(state.query)}" placeholder="搜索问题、地区、关键词"></div>${filtered.length?`<div class="grid-2">${filtered.map(topicCard).join('')}</div>`:empty('从一个具体问题开始','例如：一项政策的实施，可能如何改变区域贸易？',create('topics','创建议题','','primary'))}`;}
async function topicDetail(id){
 const b=await api(`/topics/${encodeURIComponent(id)}/bundle`);state.bundle=b;const t=b.topic;const evidence=items(b.evidence),claims=items(b.claims),judgments=items(b.judgments),scenarios=items(b.scenarios),paths=items(b.impact_paths),events=items(b.events),reviews=items(b.reviews),metrics=items(b.observations);const d=await api(`/dashboard?window=7d&topic_id=${encodeURIComponent(id)}&limit=10`);const changes=items(d.changes||d);const briefs=items(await api(`/briefs?topic_id=${encodeURIComponent(id)}&limit=50`));
 const evidenceIds=new Set(evidence.filter(e=>(!state.materialFilter||e.material_type===state.materialFilter)&&(!state.verificationFilter||e.status===state.verificationFilter)).map(e=>e.id));
 const filteredEvents=events.filter(e=>(!state.verificationFilter||e.verification_status===state.verificationFilter)&&(!state.materialFilter||(e.evidence_version_ids||[]).some(v=>evidenceIds.has(v.split('@')[0]))));
 filteredEvents.sort((a,b)=>{const key=e=>state.timeline==='event'?e.occurred_at:e.published_at||(e.evidence_version_ids||[]).map(v=>evidence.find(x=>x.id===v.split('@')[0])?.published_at).filter(Boolean).sort((a,b)=>timeOrder(a)-timeOrder(b)).at(0);return timeOrder(key(b))-timeOrder(key(a));});
 const sections=[['scope','研究问题与范围'],['latest','最新变化'],['current','当前判断'],['timeline','事件时间线'],['evidence','证据与分歧'],['scenarios','发展情景'],['paths','影响路径'],['country','国家背景'],['versions','版本与复盘']];
 return head('TOPIC DOSSIER',t.question,t.rationale||'关注理由尚未记录',`${edit('topics',t,'编辑议题')}${action('follow',t.followed?'取消关注':'关注议题',`data-id="${esc(id)}"`)}${action('make-brief','生成模板简报',`data-id="${esc(id)}"`)}${action('export','导出研究',`data-id="${esc(id)}"`,'primary')}`)+`<div class="grid-main"><div>${panel('研究问题与范围',`<div class="panel-body"><div class="badges" style="margin-bottom:14px">${badge(t.status)}${t.followed?badge('ready','已关注'):''}${history('topics',t)}</div>${textKv([['地区',(t.regions||[]).join(' · ')||'未记录'],['参与方',(t.actors||[]).join(' · ')||'未记录'],['研究期限',t.time_range||'未知'],['关键词',(t.keywords||[]).join('、')||'未设置'],['排除词',(t.exclude_keywords||[]).join('、')||'未设置']])}${coverageNotice(d.coverage)}</div>`,'','01','scope')}${panel('最新变化',changes.length?changes.map(changeCard).join(''):empty('近 7 天暂无已登记变化','可查看更早的变化窗口或继续补充材料。'),'','02','latest')}${panel('当前判断',judgments.length?judgments.map(j=>judgmentCard(j)).join(''):empty('尚未形成判断','先登记依据，再列出自己的解释、假设与反证。',create('judgments','形成首个判断',id,'primary')),create('judgments','＋ 新判断',id),'03','current')}${panel('事件时间线',`<div class="panel-body"><div class="toolbar"><div class="segmented">${action('timeline-mode','事件时间','data-value="event"',state.timeline==='event'?'selected':'')}${action('timeline-mode','材料发布时间','data-value="published"',state.timeline==='published'?'selected':'')}</div><div class="actions"><select aria-label="时间线材料类型" data-filter="timeline-material"><option value="">全部材料类型</option>${['article','official','statement','data','excerpt'].map(v=>`<option value="${v}" ${state.materialFilter===v?'selected':''}>${esc(label(v))}</option>`).join('')}</select><select aria-label="时间线核查状态" data-filter="timeline-verification"><option value="">全部核查状态</option>${['unverified','reviewed','disputed'].map(v=>`<option value="${v}" ${state.verificationFilter===v?'selected':''}>${label(v)}</option>`).join('')}</select></div></div>${filteredEvents.length?`<div class="timeline">${filteredEvents.map(e=>eventCard(e,claims,evidence)).join('')}</div>`:empty('尚无符合筛选的事件','事件时间未知时保留未知；主体的声明可以先登记为说法。')}${events.length?`<div class="map-wrap" data-map="topic"></div><div class="map-note">点击事件的“在地图中查看”可联动选择。国家级记录仅高亮区域。</div>`:''}</div>`,`${create('claims','＋ 说法',id)}${create('events','＋ 事件',id)}`,'04','timeline')}${panel('证据与分歧',`${evidence.length?evidence.map(e=>evidenceCard(e,id)).join(''):empty('还没有材料','原文链接、允许的摘录和时间，是研究的起点。')}${claims.length?`<div class="panel-body"><h3>已登记的说法 · 并列保留不同主张</h3>${claims.map(c=>claimCard(c)).join('')}</div>`:''}`,create('evidence','＋ 登记材料',id),'05','evidence')}${panel('发展情景',scenarios.length?scenarios.map(scenarioCard).join(''):empty('尚未建立情景','有足够材料时，可维护 2—3 个竞争性情景；没有反证时如实记录检索范围。'),create('scenarios','＋ 情景',id),'06','scenarios')}${panel('影响路径',paths.length?paths.map(pathCard).join(''):empty('尚未建立影响路径','把传导过程拆为相邻关系，逐段注明证据和待验证项。'),create('impact-paths','＋ 路径',id),'07','paths')}${panel('国家背景',metricsTable(metrics),create('metrics','＋ 登记指标',id),'08','country')}${panel('版本与复盘',`<div class="panel-body"><p class="small-text muted">所有修订保留不可变快照。打开各记录的版本按钮查看当时材料，后续资料不会混入旧判断。</p>${briefs.length?`<h3>已保存的模板简报</h3>${briefs.map(brief=>`<div class="record-top" style="margin:10px 0"><span class="small-text">${esc(date(brief.generated_at))} ${badge(brief.status)}${brief.missing_evidence?badge('unknown','缺乏证据支持'):''}</span>${action('view-brief','查看简报',`data-id="${esc(brief.id)}"`,'small')}</div>`).join('')}`:''}${reviews.length?reviews.map(reviewCard).join(''):empty('暂无复盘记录','到期后对照结果条件，保留符合、不符合、部分符合或无法判定的理由。')}</div>`,create('reviews','＋ 复盘',id),'09','versions')}</div><aside class="sticky-aside">${panel('档案目录',`<nav class="anchor-list" aria-label="议题档案章节">${sections.map(([anchor,title],i)=>`<a href="#${anchor}" data-action="anchor" data-target="${anchor}">${String(i+1).padStart(2,'0')} · ${title}</a>`).join('')}</nav>`)}${panel('资料概览',`<div class="panel-body">${textKv([['材料记录',evidence.length],['事件／说法',`${events.length} / ${claims.length}`],['判断／情景',`${judgments.length} / ${scenarios.length}`],['资料截至',date(evidence.map(e=>e.collected_at||e.updated_at).sort().at(-1))]])}<p class="small-text muted">资料截至时间反映登记范围，不表示覆盖所有相关信息。</p></div>`)}</aside></div>`;
}
function judgmentCard(j){return `<article class="record"><div class="record-top"><div class="badges">${badge(j.status)}${badge('neutral',label(j.judgment_type))}<span class="small-text muted">分析置信度：${esc(label(j.confidence))}</span></div><div class="actions">${edit('judgments',j)}${history('judgments',j)}</div></div><div class="prose">${esc(j.conclusion)}</div>${assumptionNotice(j)}${cite(j.evidence_version_ids)}<div class="record-meta"><span>适用至 ${esc(j.valid_until||'未指定')}</span><span>复查 ${esc(j.review_date||'未指定')}</span><span>${esc(j.author||'作者未填写')}</span></div><details style="margin-top:12px"><summary class="small-text">依据、假设与反证</summary><div style="margin-top:12px">${textKv([['置信理由',j.confidence_reason||'未记录'],['假设',lines(j.assumptions)||'未记录'],['判定条件',j.outcome_criteria||'不适用或尚未记录'],['修订原因',j.change_reason||'首次登记']])}<p class="small-text muted">反对证据</p>${j.opposing_evidence_version_ids?.length?cite(j.opposing_evidence_version_ids):'<span class="small-text muted">尚未登记</span>'}</div></details><div class="record-actions">${action('review','记录复盘',`data-id="${esc(j.id)}"`,'small ghost')}</div></article>`;}
function eventCard(e,claims,evidence){const publication=(e.evidence_version_ids||[]).map(v=>evidence.find(x=>x.id===v.split('@')[0])?.published_at).filter(Boolean).sort((a,b)=>timeOrder(a)-timeOrder(b)).at(0);return `<article class="timeline-item" id="event-${esc(e.id)}"><div class="timeline-date">${state.timeline==='event'?`发生 ${esc(date(e.occurred_at,e.time_precision))} · 精度：${esc(label(e.time_precision))}`:`材料发布 ${esc(date(publication))}`}</div><div class="record-top"><h3>${esc(e.title)}</h3>${badge(e.verification_status)}</div><div class="small-text muted">${esc(e.location?.name||e.location?.country_code||'位置未知')} · ${esc(label(e.location?.precision||'unknown'))}级位置</div>${(e.claim_ids||[]).map(id=>claims.find(c=>c.id===id)).filter(Boolean).map(claimCard).join('')}${cite(e.evidence_version_ids)}<div class="record-actions">${edit('events',e)}${history('events',e)}${action('map-event','在地图中查看',`data-id="${esc(e.id)}"`,'small ghost')}</div></article>`;}
function claimCard(c){return `<div class="claim"><div class="record-top"><strong>${esc(c.subject)}的说法</strong>${badge(c.dispute_status)}</div>${paragraphs(c.statement)}<div class="small-text muted">归属：${esc(c.attribution||'未补充')} · 说法不等于已证实事实</div>${cite(c.evidence_version_ids)}<div class="record-actions">${edit('claims',c)}${history('claims',c)}</div></div>`;}
function evidenceCard(e,topicId=''){return `<article class="record"><div class="record-top"><div class="record-title"><a href="#/evidence/${esc(e.id)}">${esc(e.title)}</a></div>${badge(e.status)}</div><div class="record-meta"><span>${esc(e.publisher||e.source_id||'来源未知')}</span><span>${esc(label(e.material_type))}</span><span>${esc(e.language||'语言未知')}</span><span>发布 ${esc(date(e.published_at))}</span></div><div class="record-meta"><span>采集 ${esc(date(e.collected_at))}</span><span>${e.origin_evidence_id?'已识别转引关系':'来源独立性尚未确认'}</span><span>v${esc(e.version)}</span></div>${e.excerpt&&e.rights?.display!==false?`<div class="prose">${esc(e.excerpt.length>240?e.excerpt.slice(0,240)+'…':e.excerpt)}</div>`:''}<div class="record-actions"><a class="button small" href="#/evidence/${esc(e.id)}">材料详情</a>${edit('evidence',e)}${topicId?action('unlink','移出此议题',`data-id="${esc(e.id)}" data-topic="${esc(topicId)}"`,'small ghost'):''}</div></article>`;}
function scenarioCard(s){return `<article class="record"><div class="record-top"><h3>${esc(s.title)}</h3><div class="actions">${badge(s.status)}${edit('scenarios',s)}${history('scenarios',s)}</div></div>${paragraphs(s.description)}${cite(s.evidence_version_ids)}<div style="margin-top:13px">${textKv([['假设',lines(s.assumptions)||'未记录'],['观察信号',lines(s.signals)||'未记录'],['失效条件',s.invalidation_conditions||'未记录'],['反证检索',s.counterevidence_search||'未记录'],['适用／复查',`${s.valid_until||'未知'} / ${s.review_date||'未指定'}`]])}</div>${s.opposing_evidence_version_ids?.length?cite(s.opposing_evidence_version_ids):'<p class="small-text muted">反对材料：尚未登记，不能推断不存在反证。</p>'}</article>`;}
function pathCard(p){const nodes=p.nodes||[];return `<article class="record"><div class="record-top"><h3>${esc(p.title)}</h3><div class="actions">${badge(p.status)}${edit('impact-paths',p)}${history('impact-paths',p)}</div></div><div class="flow-path">${nodes.map((n,i)=>`${i?'<span class="flow-arrow">→</span>':''}<div class="flow-node">${esc(typeof n==='string'?n:n.label||n.title||n.id)}</div>`).join('')}</div>${(p.edges||[]).map(edge=>`<div class="path-edge"><div class="badges"><strong>${esc(nodes.find(n=>n.id===edge.from)?.label||edge.from)} → ${esc(nodes.find(n=>n.id===edge.to)?.label||edge.to)}</strong>${badge(edge.needs_review?'needs_review':edge.status,edge.needs_review?'待重审':edge.status==='unverified'?'待验证':label(edge.status))}</div>${paragraphs(edge.note,'未补充关系说明')}${cite(edge.evidence_version_ids)}</div>`).join('')}<p class="small-text muted" style="margin-top:12px">关联不自动构成因果；每段证据的时间和地区口径应分别核对。</p></article>`;}
function reviewCard(r){return `<div class="record"><div class="record-top"><div class="badges">${badge(r.outcome==='indeterminate'?'unknown':'neutral',label(r.outcome))}<span class="small-text muted">判断 v${esc(r.judgment_version)} · ${esc(date(r.created_at))}</span></div>${history('reviews',r)}</div>${paragraphs(r.rationale)}${cite(r.evidence_version_ids)}<span class="small-text muted">复盘人 ${esc(r.author||'未记录')}</span></div>`;}
function metricsTable(metrics){return metrics.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>国家 / 指标</th><th>数值 / 单位</th><th>观测期</th><th>发布 / 登记时间</th><th>来源 / 版本</th></tr></thead><tbody>${metrics.map(m=>`<tr><td><strong>${esc(m.country_code)}</strong><br>${esc(m.indicator)}</td><td>${m.value===null||m.value===undefined?'未知':esc(Number(m.value).toLocaleString('zh-CN'))}<br><span class="muted">${esc(m.unit||'单位未知')}</span></td><td>${esc(m.period||'未知')}<br><span class="muted">${esc(m.frequency||'频率未知')}</span></td><td>${esc(date(m.published_at))}<br><span class="muted">登记 ${esc(date(m.collected_at||m.created_at))}</span></td><td>${esc(m.source_id||'未知')}${cite(m.evidence_version_ids)}${edit('metrics',m)}${history('metrics',m)}</td></tr>`).join('')}</tbody></table></div><div class="map-note">数值未知不等于 0。指标以观测期为准，重新采集不会使年度数据变为实时数据。</div>`:empty('当前范围尚无背景指标','在“编辑议题”选择国家背景代码（如 USA），并核对免费 WDI 来源是否已采集。也可手工登记带观测期和出处的数据。');}
async function evidencePage(){const q=new URLSearchParams({offset:String(state.offset),limit:String(state.limit),search:state.query});const result=await api('/evidence?'+q);const independence=result.source_counts;const chainInfo=independence?`<div class="notice info">当前结果报道记录 ${esc(independence.report_count)} · 已识别来源链 ${esc(independence.identified_source_chain_count)} · 独立性未确认 ${esc(independence.independence_unconfirmed_count)}。来源链数量不等于事实证实次数。</div>`:'';return head('EVIDENCE LIBRARY','证据资料库','保存原始出处与历史版本，让每个判断都能追溯到当时的材料。',create('evidence','＋ 登记材料','','primary'))+`<div class="toolbar"><span class="small-text muted">${esc(result.total)} 条材料 · 不把转载数量当成独立证实</span><input type="search" aria-label="搜索材料" data-filter="search" placeholder="搜索标题、来源或摘录" value="${esc(state.query)}"></div>`+chainInfo+panel('材料记录',items(result).length?items(result).map(e=>evidenceCard(e)).join('')+pagination(result):empty('暂无材料','从官方文件、原文链接或允许的摘录开始。'));}
async function evidenceDetail(id){const current=await api('/evidence/'+encodeURIComponent(id));const requestedVersion=new URLSearchParams(location.hash.split('?')[1]||'').get('version');let e=current;let snapshots=null;if(requestedVersion){snapshots=items(await api(`/evidence/${encodeURIComponent(id)}/history`));e=snapshots.find(x=>String(x.version)===requestedVersion)||current;}state.detail=current;let dependencies=current.relations; if(!dependencies)dependencies={claims:state.claims.filter(c=>(c.evidence_version_ids||[]).some(v=>v.split('@')[0]===id)),judgments:state.judgments.filter(j=>[...(j.evidence_version_ids||[]),...(j.opposing_evidence_version_ids||[])].some(v=>v.split('@')[0]===id))};const old=e.version!==current.version;const channels=e.channels||[];const topicIds=e.topic_ids||[e.topic_id].filter(Boolean);const similarity=await similarityPanel(current);return head('EVIDENCE RECORD',e.title,`${e.publisher||'发布机构未知'} · ${e.language||'语言未知'} · ${label(e.material_type)}`,`${edit('evidence',current)}${history('evidence',current)}${current.deleted?'':action('correction','登记更正 / 撤回',`data-id="${esc(id)}"`,'primary')}`)+`${current.deleted?'<div class="notice">此材料已在回收站，保留引用占位。可前往本地运行页面显式恢复。</div>':''}${old?`<div class="notice">正在查看被引用的历史版本 v${esc(e.version)}。当前材料已更新至 v${esc(current.version)}，历史引用身份保留，正文按当前许可与期限展示。 <a href="#/evidence/${esc(id)}">查看当前版本</a></div>`:''}<div class="grid-main"><div>${panel('原始材料',`<div class="panel-body"><div class="badges" style="margin-bottom:15px">${badge(e.status)}${badge('neutral',`固定版本 v${e.version}`)}</div>${kv([['原文链接',link(e.url,e.url||'原文')],['发布机构',esc(e.publisher||'未知')],['作者',esc(e.author||'未知')],['发布时间',esc(date(e.published_at))],['来源更新',esc(date(e.source_updated_at))],['采集时间',esc(date(e.collected_at))],['发现时间',esc(date(e.discovered_at))]])}<h3 style="margin-top:24px">合法摘录 · 原文</h3>${e.content_restricted||e.status==='restricted'||e.rights?.display===false?`<div class="notice">${e.content_policy?.expired||e.content_expired?'正文保留期限已到，仅保留允许的元数据、笔记与引用。':'此材料展示受限，仅显示允许的元数据。'}</div>`:paragraphs(e.excerpt,'未保存摘录；可通过原文链接核对。')}${e.translation?`<h3 style="margin-top:22px">人工译文</h3>${paragraphs(e.translation)}`:''}<h3 style="margin-top:22px">研究备注</h3>${paragraphs(e.notes)}</div>`)}${panel('出处与出现渠道',`<div class="panel-body">${e.origin_evidence_id?`<p>原始出处：<a href="#/evidence/${esc(e.origin_evidence_id)}">${esc(state.evidence.find(x=>x.id===e.origin_evidence_id)?.title||e.origin_evidence_id)}</a></p>`:'<p class="muted">原始出处与独立性尚未确认。</p>'}${channels.length?channels.map(c=>`<div class="record-meta">${link(typeof c==='string'?c:c.url,typeof c==='string'?c:c.title||c.url)} <span>${esc(typeof c==='object'?c.publisher||c.source_id||'':'')}</span></div>`).join(''):'<p class="small-text muted">尚无额外出现渠道</p>'}<div class="notice info" style="margin-top:18px">多篇报道可能转引同一来源。精确重复可以归并，标题相似只用于候选检查，不能自动合并事件。</div><div class="actions">${action('split-evidence','拆分误合并',`data-id="${esc(id)}"`,'small')}</div></div>`)}${similarity}${panel('引用此材料的研究',`<div class="panel-body">${Object.entries(dependencies).filter(([,v])=>Array.isArray(v)).map(([kind,records])=>`<h3>${esc(({claim:'说法',event:'事件',judgment:'判断',scenario:'情景',impact_path:'影响路径',claims:'说法',events:'事件',judgments:'判断',scenarios:'情景',impact_paths:'影响路径'})[kind]||kind)}</h3>${records.length?records.map(r=>`<p><span>${esc(r.conclusion||r.statement||r.title||r.id)}</span> ${action('history','查看引用记录',`data-kind="${({claim:'claims',event:'events',judgment:'judgments',scenario:'scenarios',impact_path:'impact-paths'})[kind]||kind}" data-id="${esc(r.id)}"`,'small ghost')}${cite((r.evidence_version_ids||[]).filter(v=>v.split('@')[0]===id))}</p>`).join(''):'<p class="muted small-text">尚无登记引用</p>'}`).join('')||'<p class="muted">尚无登记引用</p>'}</div>`)}</div><aside>${panel('关联议题',`<div class="panel-body">${topicIds.length?topicIds.map(t=>`<p><a href="#/topics/${esc(t)}">${esc(topicName(t))}</a></p>`).join(''):'<span class="muted small-text">未关联议题</span>'}</div>`)}${panel('使用范围',`<div class="panel-body">${textKv(['store','display','export','ai'].map(k=>[({store:'存储',display:'展示',export:'导出',ai:'AI使用'})[k],(e.effective_rights||e.rights)?.[k]===true?'已允许':(e.effective_rights||e.rights)?.[k]===false?'不允许':(({none:'不允许',metadata:'仅元数据',link:'仅链接',excerpt:'仅合法摘录',full:'已允许登记范围',allowed:'已允许'})[(e.effective_rights||e.rights)?.[k]]||'未知')]))}<p class="small-text muted">保留链接不意味着拥有原文再分发权限。当前 AI 功能关闭。</p></div>`)}</aside></div>`;}
async function judgmentsPage(){const query=new URLSearchParams({limit:String(state.limit),offset:String(state.offset)});if(state.judgmentStatus)query.set('status',state.judgmentStatus);if(state.judgmentType)query.set('judgment_type',state.judgmentType);if(state.judgmentTopic)query.set('topic_id',state.judgmentTopic);if(state.reviewDue)query.set('due_before',new Date().toISOString().slice(0,10));if(state.query)query.set('search',state.query);if(state.conclusionChanged)query.set('changed','true');if(state.reviewBefore)query.set('due_before',state.reviewBefore);const [result,reviews,needs]=await Promise.all([api('/judgments?'+query),api('/reviews?limit='+state.limit+'&offset='+(state.reviewOffset||0)),api('/judgments?status=needs_review&limit=1')]);const records=items(result);return head('JUDGMENTS & REVIEW','我的判断','保留曾经如何思考，也记录为什么改变。已审阅并不代表系统证明了判断。',create('judgments','＋ 新判断','','primary'))+`<div class="stats"><div class="stat"><div class="stat-label">符合筛选的判断</div><div class="stat-value">${result.total}</div></div><div class="stat"><div class="stat-label">待重审</div><div class="stat-value">${needs.total}</div></div><div class="stat"><div class="stat-label">已有复盘</div><div class="stat-value">${reviews.total}</div></div><div class="stat"><div class="stat-label">结果无法判定</div><div class="stat-value">${reviews.summary?.indeterminate_count??0}</div><div class="stat-foot">单独记录，不计为预测成败</div></div></div><div class="toolbar"><input type="search" aria-label="搜索全部判断" data-filter="search" value="${esc(state.query)}" placeholder="搜索全部判断">${action('apply-search','搜索判断')}<div class="actions"><select data-filter="judgment-topic" aria-label="判断所属议题"><option value="">全部议题</option>${state.topics.map(t=>`<option value="${esc(t.id)}" ${state.judgmentTopic===t.id?'selected':''}>${esc(t.question)}</option>`).join('')}</select><select data-filter="judgment-status" aria-label="判断状态"><option value="">全部状态</option>${['draft','reviewed','needs_review','withdrawn'].map(v=>`<option value="${v}" ${state.judgmentStatus===v?'selected':''}>${label(v)}</option>`).join('')}</select><select data-filter="judgment-type" aria-label="判断类型"><option value="">全部类型</option>${['explanation','prediction'].map(v=>`<option value="${v}" ${state.judgmentType===v?'selected':''}>${label(v)}</option>`).join('')}</select><label class="small-text check-field"><input type="checkbox" data-filter="review-due" ${state.reviewDue?'checked':''}>只看已到复查日期</label><label class="small-text">复查截至 <input type="date" aria-label="复查截至日期" data-filter="review-before" value="${esc(state.reviewBefore||'')}"></label><label class="small-text check-field"><input type="checkbox" data-filter="conclusion-changed" ${state.conclusionChanged?'checked':''}>结论曾变更</label></div></div>${panel('判断记录',records.length?records.map(j=>`<div class="record-meta" style="padding:14px 22px 0"><a href="#/topics/${esc(j.topic_id)}">${esc(topicName(j.topic_id))}</a></div>${judgmentCard(j)}`).join('')+pagination(result):empty('暂无符合条件的判断','建立议题后，记录解释或可判定预测，并指定下一次复查日期。'))}${panel('复盘记录',items(reviews).length?items(reviews).map(reviewCard).join('')+pagination(reviews,state.reviewOffset||0,'review-page'):empty('暂无复盘记录','从判断卡片进入“记录复盘”。'))}`;}
async function sourcesPage(){const [result,coverage,jobs]=await Promise.all([api('/sources?limit=200'),api('/sources/coverage'),api('/sources/jobs?limit=20')]);state.sources=items(result);return head('SOURCES & COVERAGE','来源管理','分别查看连通性、覆盖范围与数据年龄。自动采集与手动刷新共享同一免费预算。',create('sources','＋ 登记来源','','primary'))+coverageNotice(coverage)+`<div class="source-grid">${state.sources.map(sourceCard).join('')}</div><div class="notice info" style="margin-top:20px">免费 API、网页可读与内容可再分发是不同权限。许可未知的来源仅登记链接；AI、航空、船舶、专业行情等预留能力未接入，没有模拟轨迹。</div>${panel('采集任务与缺口',items(jobs).length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>来源 / 议题</th><th>任务状态</th><th>请求 / 尝试</th><th>检查区间与缺口</th><th>创建时间</th></tr></thead><tbody>${items(jobs).map(j=>`<tr><td>${esc(state.sources.find(s=>s.id===j.source_id)?.name||j.source_id)}<br><span class="muted">${esc(topicName(j.topic_id))}</span></td><td>${badge(j.state||j.status)}${j.error?`<p class="small-text">${esc(j.error)}</p>`:''}</td><td>${esc(j.request_count??0)} / ${esc(j.attempts??0)}</td><td>${esc(j.gap_start||'—')} → ${esc(j.gap_end||'—')}<br>${esc(j.reason||j.gap_reason||'')}</td><td>${esc(date(j.created_at))}</td></tr>`).join('')}</tbody></table></div>`:empty('尚无采集任务','启用已审核的免费来源后，可手动触发一次检查。'))}`;}
function sourceCard(s){const reserved=['paid','ai','aviation','shipping','market_data'].some(x=>String(s.adapter||'').includes(x))||s.paid===true||s.is_paid===true;const quota=Math.max(0,Math.min(100,(s.requests_today||0)/Math.max(1,s.budget_daily||1)*100));return `<article class="source-card"><div class="record-top"><div><h3>${esc(s.name)}</h3><span class="small-text muted">${esc(s.domain||s.adapter)} · ${esc((s.languages||[]).join(' / ')||'语言覆盖未知')}</span></div>${badge(s.status)}</div>${textKv([['最后尝试',date(s.last_attempt)],['最后成功',date(s.last_success)],['源数据截至',date(s.data_as_of)],['下次检查',date(s.next_check)],['地区覆盖',(s.regions||[]).join('、')||'未记录'],['免费请求',`${s.requests_today??0} / ${s.budget_daily??0} 次 / 日`]])}<div class="source-meter" aria-label="免费请求使用比例"><span style="width:${quota}%"></span></div>${s.last_error?`<div class="notice" style="margin-top:14px">${esc(s.last_error)}</div>`:''}${s.coverage_gaps?.length?`<div class="notice">${esc(s.coverage_gaps.map(g=>typeof g==='string'?g:JSON.stringify(g)).join('；'))}</div>`:''}<div class="source-footer"><span class="small-text">${link(s.license_url,'授权依据')}</span><div class="actions">${reserved?badge('not_configured','扩展接口 · 默认关闭'):`${edit('sources',s,'设置')}${action('refresh-source','检查来源',`data-id="${esc(s.id)}" ${s.enabled&&s.adapter!=='manual'?'':'disabled'}`,'small')}`}</div></div></article>`;}
async function settingsPage(){const b=state.bootstrap;const caps=b.capabilities||{};return head('LOCAL OPERATIONS','本地运行与数据','程序目录与研究数据分离。日常运行不依赖 GitHub、模型服务或收费接口。')+`<div class="settings-grid">${panel('当前实例',`<div class="panel-body">${textKv([['程序版本',b.version||'未知'],['数据目录',b.data_dir||'未知'],['数据库版本',b.schema_version??b.database_version??'未知'],['访问地址',location.origin],['运行方式','单机私有 · SQLite 持久化']])}<div class="notice info">更换程序版本时继续指向当前数据目录。数据目录内包含研究记录、不可变历史与阅读进度。</div></div>`)}${panel('能力与费用',`<div class="panel-body">${textKv([['人工研究','可用'],['免费数据','按来源授权与配额启用'],['AI 能力',label(caps.ai?.status||caps.ai||'disabled')],['收费数据',caps.paid_data?.status||caps.paid_data||'默认关闭'],['外部消息','未启用']])}<p class="small-text muted">来源失败时使用已有合法缓存。应用不会自动购买、充值或切换到收费服务。</p><a href="#/sources">管理免费来源 →</a></div>`)}${panel('启动与配置检查',`<div class="panel-body"><p>双击项目根目录的启动入口，健康检查通过后浏览器自动打开；再次启动会复用已有实例。</p><p class="small-text muted">使用停止入口关闭本项目服务，研究数据保留。缺失可选密钥不阻断人工研究。</p><p class="small-text muted">配置检查分为本地依赖／数据目录检查与外部来源联网探测。修复方式见仓库 README。</p>${action('check-health','检查当前服务','','small')}</div>`)}${panel('备份、恢复与更新',`<div class="panel-body"><p>使用项目本地运维入口创建一致性备份，备份包包含清单校验，不包含默认服务密钥。</p><p class="small-text muted">恢复先在临时目录校验；替换已有资料前保留恢复点，并要求明确选择替换。更新遇到未提交修改会停止，不清理工作区。</p><p class="small-text muted">迁移失败需成对恢复程序与数据库。升级后已有新写入时，不会静默使用旧快照覆盖。</p><a href="https://github.com/kokostad2000/world-insight" target="_blank" rel="noopener noreferrer">项目仓库 ↗</a></div>`)}${panel('七天真实试运行',`<div class="panel-body"><div class="badges">${badge('unknown','M4 待真实观察')}</div><p style="margin-top:13px">准备 5 个真实议题，每天记录查看关键变化所用时间、遗漏、来源覆盖及判断修订。</p><p class="small-text muted">只有实际完成连续七天观察后才能验收。测试样本和模拟记录不能替代真实使用。</p></div>`)}</div>`+(await lifecyclePanel());}
async function mapPage(){const [events,metrics]=await Promise.all([api('/events?limit=200'),api('/metrics?limit=200')]);state.mapEvents=items(events);state.mapMetrics=items(metrics);const countries=[...new Set([...state.mapEvents.map(e=>e.location?.country_code),...state.mapMetrics.map(m=>m.country_code)].filter(Boolean))].sort();return head('GEOGRAPHIC CONTEXT','地图与国家背景','地图帮助理解研究位置与范围；坐标未知时保留国家或区域精度。')+`<div class="toolbar"><span class="small-text muted">${state.mapEvents.length} 条已登记事件 · 不代表全球完整覆盖</span><select data-filter="map-country" aria-label="选择国家"><option value="">全部已登记国家</option>${countries.map(c=>`<option value="${esc(c)}" ${state.mapCountry===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div>${panel('事件位置',`<div class="map-wrap" data-map="all"></div><div class="map-legend"><span><i></i>事件仅精确到国家 / 区域</span><span><i class="point"></i>有明确来源的坐标</span></div><div class="map-note">Natural Earth 静态公共领域底图。国界用于研究背景，不代表对争议地区的立场；无航空或船舶轨迹。</div>`)}<div class="grid-main"><div>${panel('国家指标',metricsTable(state.mapMetrics.filter(m=>!state.mapCountry||m.country_code===state.mapCountry)))}</div><aside>${panel('地图中的事件',state.mapEvents.filter(e=>!state.mapCountry||e.location?.country_code===state.mapCountry).map(e=>`<article class="record map-event ${state.selectedEvent===e.id?'selected':''}" data-event-id="${esc(e.id)}"><h3>${esc(e.title)}</h3><div class="small-text muted">${esc(date(e.occurred_at,e.time_precision))}<br>${esc(e.location?.name||e.location?.country_code||'地点未知')} · ${esc(label(e.location?.precision||'unknown'))}</div><div class="record-actions">${action('map-event','选择位置',`data-id="${esc(e.id)}"`,'small')}<a class="button small" href="#/topics/${esc(e.topic_id)}">议题</a></div></article>`).join('')||empty('暂无事件位置','只有真实登记的位置才会显示。'))}</aside></div>`;}
function countryCode(feature){const p=feature.properties||{};return p.ADM0_A3||p.adm0_a3||p.ISO_A3||p.iso_a3||p.ISO_A3_EH||p.SOV_A3||feature.id;}
function pathForGeometry(geometry){const rings=geometry.type==='Polygon'?geometry.coordinates:geometry.type==='MultiPolygon'?geometry.coordinates.flat():[];return rings.map(ring=>{let prev=null;return ring.map(([lon,lat],i)=>{const x=(lon+180)*2.5,y=(90-lat)*2.5;const breakLine=prev!==null&&Math.abs(lon-prev)>180;prev=lon;return `${i===0||breakLine?'M':'L'}${x.toFixed(2)},${y.toFixed(2)}`;}).join(' ')+' Z';}).join(' ');}
async function renderMaps(){const containers=[...document.querySelectorAll('[data-map]')];if(!containers.length)return;try{if(!mapCache){const response=await fetch('/assets/world-countries.geojson');if(!response.ok)throw new Error('底图资源尚未就绪');mapCache=await response.json();}for(const container of containers){const events=container.dataset.map==='topic'?items(state.bundle?.events):state.mapEvents||[];const selected=events.find(e=>e.id===state.selectedEvent);const filtered=events.filter(e=>!state.mapCountry||container.dataset.map==='topic'||e.location?.country_code===state.mapCountry);const codes=new Set((selected?[selected]:filtered).map(e=>e.location?.country_code).filter(Boolean));const pins=(selected?[selected]:filtered).filter(e=>eventCoordinates(e));container.innerHTML=`<svg class="world-map" viewBox="0 0 900 450" role="img" aria-label="真实静态国家底图与登记事件位置"><rect width="900" height="450" fill="#edf2f2"/>${mapCache.features.map(feature=>`<path d="${pathForGeometry(feature.geometry)}" class="map-country ${codes.has(countryCode(feature))?'selected':''}"><title>${esc(feature.properties?.NAME_ZH||feature.properties?.ADMIN||feature.properties?.name||countryCode(feature))}</title></path>`).join('')}${pins.map(e=>{const [lon,lat]=eventCoordinates(e);return `<circle cx="${(lon+180)*2.5}" cy="${(90-lat)*2.5}" r="4.5" class="map-pin"><title>${esc(e.title)}</title></circle>`;}).join('')}</svg>${selected?`<div class="map-note">已选择：${esc(selected.title)} · ${esc(selected.location?.name||selected.location?.country_code||'未知位置')}（${esc(label(selected.location?.precision))}级）${!eventCoordinates(selected)?' · 未生成精确坐标点':''}</div>`:''}`;}}catch(error){containers.forEach(c=>c.innerHTML=empty('底图暂不可用',`${error.message}。事件与国家指标仍可通过列表阅读；未生成替代轮廓或虚构坐标。`));}}

function openDialog(title,body,footer=''){const dialog=$('#editor-dialog');dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2>${action('close-dialog','关闭','','ghost small')}</div>${body}${footer}`;if(!dialog.open)dialog.showModal();}
function closeDialog(){const dialog=$('#editor-dialog');dialog.close();dialog.innerHTML='';dialogContext=null;}
async function openEditor(kind,id='',topicId='',prefill={}){await context();const original=id?await api(`/${kind}/${encodeURIComponent(id)}`):null;const defaults={topic_id:topicId||state.bundle?.topic?.id||'',status:kind==='topics'?'active':kind==='evidence'?'unverified':'draft',followed:true,source_id:'manual',language:'zh',material_type:'official',judgment_type:'explanation',confidence:'medium',author:'本人',reviewer:'本人',missing_evidence:'',rights:{fetch:false,store:false,display:false,export:false,ai:false},budget_daily:20,interval_seconds:1800,adapter:'manual',time_precision:'unknown',location:{precision:'unknown'},outcome:'indeterminate',...prefill};if(kind==='evidence')defaults.author='';const record=original?{...original}:defaults;if(record.channels)record.channels=record.channels.map(c=>typeof c==='string'?c:c.url).filter(Boolean);const schema=schemas[kind];if(!schema)throw new Error('此记录暂不支持编辑');dialogContext={kind,original,record};openDialog(`${id?'编辑':'新建'}${titles[kind]}`,`<form id="record-form"><div class="dialog-body"><div class="editor-error" role="alert"></div>${original?`<div class="notice info">正在编辑 v${original.version}。保存会创建新版本，原版本保留。遇到并发修改会提示冲突，当前表单不会被覆盖。</div>`:''}${kind==='topics'&&!original?`<div class="field" style="margin-bottom:18px"><label for="topic-template">从研究模板开始（可继续编辑）</label><select id="topic-template"><option value="">空白议题</option>${items(state.bootstrap.templates).map((t,i)=>`<option value="${i}">${esc(t.name)}</option>`).join('')}</select><div class="hint">模板不预填任何当前局势结论。</div></div>`:''}${kind==='claims'?'<div class="notice">记录“谁说了什么”，不自动把声明变成已落实的事实。</div>':''}${kind==='sources'?'<div class="notice">只配置免费来源与明确许可的范围。此表单不启用收费或 AI 能力。</div>':''}<div class="form-grid">${schema.map(f=>renderField(f,record,state)).join('')}</div></div><div class="dialog-footer"><span class="small-text muted">* 为必填项 · 未知信息可以留空</span><div class="actions">${action('close-dialog','取消')}<button class="primary" type="submit">保存${titles[kind]}</button></div></div></form>`);$('#record-form').addEventListener('submit',saveEditor);if(kind==='topics'&&!original){$('#topic-template').addEventListener('change',event=>{const template=state.bootstrap.templates[Number(event.target.value)];if(event.target.value!==''&&template){$('[name="question"]').value=template.question;$('[name="keywords"]').value=lines(template.keywords);}});}if(kind==='reviews'){$('[name="judgment_id"]').addEventListener('change',e=>{const j=state.judgments.find(j=>j.id===e.target.value);if(j){$('[name="judgment_version"]').value=j.version;$('[name="topic_id"]').value=j.topic_id;}});}}
async function saveEditor(event){event.preventDefault();const form=event.target;const {kind,original}=dialogContext;const button=form.querySelector('button[type="submit"]');button.disabled=true;const errorBox=form.querySelector('.editor-error');errorBox.innerHTML='';try{const data=readForm(form,schemas[kind]);if(kind==='sources'){const config=data.config||{};data.config=data.adapter==='rss'?{feed_url:config.feed_url||'',topic_ids:config.topic_ids||[]}:data.adapter==='gdelt'?{query:config.query||'',topic_ids:config.topic_ids||[]}:data.adapter==='world_bank'?{countries:config.countries?.length?config.countries:['CHN','USA'],indicators:config.indicators?.length?config.indicators:['NY.GDP.MKTP.CD','SP.POP.TOTL'],topic_ids:config.topic_ids||[]}:{};data.rights.ai=false;}if(kind==='impact-paths')Object.assign(data,readPath(form));if(kind==='events'&&data.location.precision!=='coordinate'){delete data.location.lat;delete data.location.lon;}if(kind==='evidence'){data.channels=preserveChannels(original?.channels||[],data.channels||[],data.source_id);if(original){const others=(original.topic_ids||[original.topic_id]).filter(x=>x&&x!==original.topic_id);data.topic_ids=[...new Set([...others,data.topic_id].filter(Boolean))];}}if(original)data.expected_version=original.version;const result=await api(`/${kind}${original?'/'+encodeURIComponent(original.id):''}`,{method:original?'PATCH':'POST',body:data});closeDialog();toast(`${titles[kind]}已保存${result.deduplicated?'，精确重复材料已关联现有记录':''}`);if(kind==='topics'){location.hash='#/topics/'+result.id;await route();}else{if(state.route==='dashboard'&&result.topic_id)location.hash='#/topics/'+result.topic_id;else await route();}}catch(error){errorBox.innerHTML=`<div class="notice danger">${esc(error.status===409?'版本冲突：另一处已修改此记录。你的输入仍保留，请先查看当前版本，再决定如何整合。':error.message)}</div>${error.status===409?`<div class="actions">${action('conflict-current','查看数据库中的当前记录','','small')}${action('copy-draft','复制我的草稿','','small')}</div><div id="conflict-current"></div>`:''}`;errorBox.scrollIntoView({block:'center',behavior:'smooth'});button.disabled=false;}}
async function showHistory(kind,id){const result=await api(`/${kind}/${encodeURIComponent(id)}/history`);const records=items(result).slice().reverse();openDialog(`${titles[kind]||'记录'}的版本历史`,`<div class="dialog-body"><div class="notice info">每个版本显示当时的依据、作者和修订理由。旧证据引用保留原版本，不混入后来的材料。</div>${records.map(r=>`<article class="history-entry"><div class="record-top"><h3>版本 ${esc(r.version)}</h3>${badge(r.status||'neutral')}</div>${textKv([['保存时间',date(r.updated_at||r.created_at)],['操作者',r.reviewer||r.author||'未登记'],['修订原因',r.change_reason||r.correction_reason||'首次登记']])}${paragraphs(r.conclusion||r.question||r.title||r.statement||r.description||r.rationale)}${cite(r.evidence_version_ids)}${r.missing_evidence?assumptionNotice(r):''}<details><summary class="small-text muted" style="margin-top:12px">完整历史快照</summary><pre>${esc(JSON.stringify(r,null,2))}</pre></details></article>`).join('')||empty('暂无历史快照','此记录尚无可查看版本。')}</div>`);}
async function correctionDialog(id){const e=await api('/evidence/'+encodeURIComponent(id));dialogContext={kind:'correction',original:e};openDialog('登记材料更正或撤回',`<form id="correction-form"><div class="dialog-body"><div class="editor-error" role="alert"></div><div class="notice">仅在你确认实质更正后，已登记的依赖判断和情景才会被标记待重审。格式变化不应被当作事实撤回。</div><h3>${esc(e.title)} · v${e.version}</h3><div class="form-grid"><div class="field"><label for="correction-status">新状态</label><select id="correction-status" name="status"><option value="corrected">已更正</option><option value="withdrawn">已撤回</option><option value="inaccessible">原链接不可访问</option><option value="restricted">展示受限</option></select></div><div class="field"><label class="check-field"><input type="checkbox" name="substantive">我已确认这是实质更正</label></div><div class="field full"><label for="correction-reason">更正原因 *</label><textarea id="correction-reason" name="reason" required placeholder="说明原材料的变化、确认依据以及受影响内容"></textarea></div><div class="field full"><label for="correction-excerpt">修正后的摘录（可选，留空保留原值）</label><textarea id="correction-excerpt" name="excerpt"></textarea></div></div></div><div class="dialog-footer"><span class="small-text muted">旧版本与当时的引用会保留</span><button class="primary" type="submit">保存更正</button></div></form>`);$('#correction-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.target,fd=new FormData(form);const body={expected_version:e.version,status:fd.get('status'),reason:fd.get('reason'),substantive:fd.get('substantive')==='on'};if(fd.get('excerpt'))body.excerpt=fd.get('excerpt');await dialogSubmit(form,()=>api(`/evidence/${encodeURIComponent(id)}/corrections`,{method:'POST',body}),'材料更正已登记，相关依赖将通过持久化队列传播');});}
async function splitDialog(id){const e=await api('/evidence/'+encodeURIComponent(id));openDialog('拆分误合并材料',`<form id="split-form"><div class="dialog-body"><div class="editor-error" role="alert"></div><div class="notice">选择应拆出的渠道，说明理由。原材料、历史引用会保留，受影响研究需要重新检查。</div><div class="refs">${(e.channels||[]).map((c,i)=>`<label><input type="checkbox" name="channels" value="${i}">${esc(typeof c==='string'?c:c.url||c.title||JSON.stringify(c))}</label>`).join('')||'<p class="muted">没有可拆分的额外渠道</p>'}</div><div class="field" style="margin-top:16px"><label>拆分理由 *</label><textarea name="reason" required></textarea></div></div><div class="dialog-footer">${action('close-dialog','取消')}<button class="primary" type="submit">确认拆分所选渠道</button></div></form>`);$('#split-form').addEventListener('submit',async event=>{event.preventDefault();const fd=new FormData(event.target),channels=fd.getAll('channels').map(i=>e.channels[Number(i)]);await dialogSubmit(event.target,()=>api(`/evidence/${encodeURIComponent(id)}/split`,{method:'POST',body:{expected_version:e.version,channels,reason:fd.get('reason')}}),'已拆分材料并保留历史记录');});}
async function dialogSubmit(form,save,message){const button=form.querySelector('button[type="submit"]');button.disabled=true;try{await save();closeDialog();toast(message);await route();}catch(error){form.querySelector('.editor-error').innerHTML=`<div class="notice danger">${esc(error.status===409?'记录已被另一处修改，当前输入仍保留。请先查看最新记录，再重新编辑。':error.message)}</div>`;button.disabled=false;}}
function exportDialog(id){openDialog('导出议题研究包',`<div class="dialog-body"><p>导出包含来源、时间、固定证据版本、未知项和生成时间。材料按已登记权限过滤，不包含服务密钥。</p><div class="actions" style="margin-top:20px">${action('download-export','下载 Markdown',`data-id="${esc(id)}" data-format="markdown"`,'primary')}${action('download-export','下载 JSON',`data-id="${esc(id)}" data-format="json"`)}</div></div>`);}
async function downloadExport(id,format){const result=await api(`/exports?topic_id=${encodeURIComponent(id)}&format=${format}`);const content=result.content??JSON.stringify(result,null,2);const blob=new Blob([typeof content==='string'?content:JSON.stringify(content,null,2)],{type:format==='json'?'application/json;charset=utf-8':'text/markdown;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=result.filename||`world-insight-${id}.${format==='json'?'json':'md'}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('已生成研究导出包');}
function syncPathSelects(){const nodes=[...document.querySelectorAll('.path-node')].map(n=>({id:n.dataset.nodeId,label:n.querySelector('[data-node-label]').value||n.dataset.nodeId}));document.querySelectorAll('[data-edge-from],[data-edge-to]').forEach(select=>{const selected=select.value;select.innerHTML=nodes.map(n=>`<option value="${esc(n.id)}" ${n.id===selected?'selected':''}>${esc(n.label)}</option>`).join('');});}
async function dispatch(button){const actionName=button.dataset.action;switch(actionName){
 case 'reload': await route();break;
 case 'apply-search':state.query=document.querySelector('[data-filter="search"]').value;state.offset=0;await route();break;
 case 'create': await openEditor(button.dataset.kind,'',button.dataset.topic);break;
 case 'edit': await openEditor(button.dataset.kind,button.dataset.id);break;
 case 'history': await showHistory(button.dataset.kind,button.dataset.id);break;
 case 'close-dialog': closeDialog();break;
 case 'window': state.window=button.dataset.value;state.offset=0;localStorage.setItem('wi-window',state.window);await route();break;
 case 'apply-window': state.offset=0;await route();break;
 case 'page':state.offset=Number(button.dataset.offset);await route();break;
 case 'review-page':state.reviewOffset=Number(button.dataset.offset);await route();break;
 case 'notification-page':state.notificationOffset=Number(button.dataset.offset);await route();break;
 case 'mark-read':{const d=state.dashboard;const shown=items(d.changes||d);await api('/changes/read',{method:'POST',body:visibleReadPayload(d.snapshot_at,shown)});toast('已标记本页快照中展示的变化版本；核查与复查待办仍保留');await route();break;}
 case 'follow':{const t=await api('/topics/'+encodeURIComponent(button.dataset.id));await api('/topics/'+encodeURIComponent(t.id),{method:'PATCH',body:{expected_version:t.version,followed:!t.followed}});toast(t.followed?'已取消关注':'已关注此议题');await route();break;}
 case 'unlink':{const e=await api('/evidence/'+encodeURIComponent(button.dataset.id));await api('/evidence/'+encodeURIComponent(e.id),{method:'PATCH',body:{expected_version:e.version,topic_ids:(e.topic_ids||[e.topic_id]).filter(t=>t&&t!==button.dataset.topic)}});toast('已移出该议题，材料原记录与历史引用保留');await route();break;}
 case 'timeline-mode':state.timeline=button.dataset.value;await route();break;
 case 'anchor':document.getElementById(button.dataset.target)?.scrollIntoView({behavior:'smooth',block:'start'});break;
 case 'review':{const j=await api('/judgments/'+encodeURIComponent(button.dataset.id));await openEditor('reviews','',j.topic_id,{judgment_id:j.id,judgment_version:j.version});break;}
 case 'correction':await correctionDialog(button.dataset.id);break;
 case 'split-evidence':await splitDialog(button.dataset.id);break;
 case 'export':exportDialog(button.dataset.id);break;
 case 'download-export':await downloadExport(button.dataset.id,button.dataset.format);break;
 case 'refresh-source':{const result=await api('/sources/'+encodeURIComponent(button.dataset.id)+'/refresh',{method:'POST',body:{}});toast(result.status==='already_queued'?'此来源已有排队任务，未重复增加请求':'已安排来源检查；页面刷新不会直接调用外部服务');await route();break;}
 case 'map-event':state.selectedEvent=button.dataset.id;await renderMaps();document.querySelector('[data-map]')?.scrollIntoView({behavior:'smooth',block:'center'});document.querySelectorAll('.map-event').forEach(el=>el.classList.toggle('selected',el.dataset.eventId===state.selectedEvent));break;
 case 'add-node':{const nodes=[...document.querySelectorAll('.path-node')];const id='n'+Date.now();$('#path-nodes').insertAdjacentHTML('beforeend',renderPathNode({id,label:''},nodes.length));syncPathSelects();break;}
 case 'add-edge':{syncPathSelects();const nodes=[...document.querySelectorAll('.path-node')].map(n=>({id:n.dataset.nodeId,label:n.querySelector('[data-node-label]').value}));$('#path-edges').insertAdjacentHTML('beforeend',renderPathEdge({from:nodes[0]?.id,to:nodes[1]?.id,status:'unverified',evidence_version_ids:[]},document.querySelectorAll('.path-edge-edit').length,nodes,state.evidence));break;}
 case 'remove-row':button.closest('.repeat-row').remove();syncPathSelects();break;
 case 'conflict-current':{const {kind,original}=dialogContext;const latest=await api(`/${kind}/${encodeURIComponent(original.id)}`);$('#conflict-current').innerHTML=`<p class="small-text">数据库当前版本 v${esc(latest.version)}；你的草稿仍在表单中。</p><pre class="conflict-content">${esc(JSON.stringify(latest,null,2))}</pre>`;break;}
 case 'copy-draft':{const data=readForm($('#record-form'),schemas[dialogContext.kind]);await navigator.clipboard.writeText(JSON.stringify(data,null,2));toast('草稿已复制；粘贴保存后再载入新版本');break;}
 case 'view-brief':{const brief=await api('/briefs/'+encodeURIComponent(button.dataset.id));openDialog('已保存的模板简报',`<div class="dialog-body">${badge(brief.status)}${brief.status==='needs_review'?'<div class="notice">引用材料已发生更正，需重新检查这份简报。</div>':''}${brief.missing_evidence?assumptionNotice(brief):''}${paragraphs(brief.content)}${cite(brief.evidence_version_ids)}<div class="actions">${deleteButton('briefs',brief)}</div></div>`);break;}
 case 'make-brief':{const result=await api('/briefs',{method:'POST',body:{topic_id:button.dataset.id}});openDialog('议题模板简报',`<div class="dialog-body">${badge(result.status)}${result.missing_evidence?assumptionNotice(result):''}${paragraphs(result.content)}${cite(result.evidence_version_ids)}<div class="actions">${deleteButton('briefs',result)}</div></div>`);break;}
 case 'notification-read':{const n=await api('/notifications/'+encodeURIComponent(button.dataset.id));await api('/notifications/'+encodeURIComponent(n.id),{method:'PATCH',body:{expected_version:n.version,status:'read'}});toast('提醒已读；相关研究待办仍保留');state.notificationOffset=0;await route();break;}
 case 'search-references':{const control=button.closest('.reference-control');const query=control.querySelector('input[type="search"]').value.trim();const kind=control.dataset.referenceKind;const name=control.dataset.referenceField;const selected=[...control.querySelectorAll('.refs input:checked')].map(input=>({id:input.value,title:input.closest('label').innerText}));const result=await api(`/${kind}?limit=50&search=${encodeURIComponent(query)}`);const options=items(result).map(r=>({id:kind==='evidence'?versionId(r):r.id,title:kind==='evidence'?`${r.title} · v${r.version}`:`${r.subject}：${r.statement}`}));for(const item of selected)if(!options.some(o=>o.id===item.id))options.unshift(item);control.querySelector('.refs').innerHTML=options.map(o=>`<label><input type="checkbox" name="${esc(name)}" value="${esc(o.id)}" ${selected.some(s=>s.id===o.id)?'checked':''}><span>${esc(o.title)}</span></label>`).join('')||'<span class="muted small-text">未找到匹配记录；已选引用仍保留。</span>';control.querySelector('.reference-search-status').textContent=`找到 ${result.total} 条，展示最多 50 条匹配记录及已选版本。缩小关键词可查找更早材料。`;break;}
 case 'check-health':{const health=await api('/health');toast('本地服务检查完成：'+(health.status||'可用'));break;}
 }}
document.addEventListener('click',async event=>{const anchor=event.target.closest('a[href^="#/"]');if(anchor&&$('#editor-dialog').open)closeDialog();const button=event.target.closest('[data-action]');if(!button)return;event.preventDefault();if(button.disabled)return;try{await dispatch(button);}catch(error){toast(error.message);}});
document.addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target.matches('[data-filter="search"]')){event.preventDefault();state.query=event.target.value;state.offset=0;route();}});
document.addEventListener('change',async event=>{const el=event.target;const key=el.dataset.filter;if(el.matches('[data-node-label]')){syncPathSelects();return;}if(!key)return;state.offset=0;switch(key){case 'dashboard-topic':state.topicFilter=el.value;break;case 'since':state.since=el.value;return;case 'until':state.until=el.value;return;case 'search':state.query=el.value;break;case 'timeline-material':state.materialFilter=el.value;break;case 'timeline-verification':state.verificationFilter=el.value;break;case 'judgment-status':state.judgmentStatus=el.value;break;case 'judgment-type':state.judgmentType=el.value;break;case 'judgment-topic':state.judgmentTopic=el.value;break;case 'review-due':state.reviewDue=el.checked;break;case 'review-before':state.reviewBefore=el.value;state.reviewDue=false;break;case 'conclusion-changed':state.conclusionChanged=el.checked;break;case 'map-country':state.mapCountry=el.value;state.selectedEvent=null;break;}await route();});
window.addEventListener('hashchange',()=>{state.offset=0;state.reviewOffset=0;state.query='';state.bundle=null;route();});
$('#editor-dialog').addEventListener('cancel',()=>{dialogContext=null;});
installLifecycle({openDialog,closeDialog,route,toast});
installSimilarity({openDialog,closeDialog,route,toast});
route();
